CREATE TABLE BILL_STATUS_HISTORY (HISTORY_ID VARCHAR2(36) PRIMARY KEY, BILL_ID VARCHAR2(36) NOT NULL, FROM_STATUS VARCHAR2(20), TO_STATUS VARCHAR2(20) NOT NULL, REASON_CODE VARCHAR2(40) NOT NULL, CHANGED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT FK_BILL_HISTORY_BILL FOREIGN KEY (BILL_ID) REFERENCES BILL(BILL_ID));
